        self.assertIn("<h1>news.example</h1>", s2.info_page(s2.create("ann", "https://news.example/")))
        s3 = m.Shortener(Fetcher("<title>" + "t" * 500 + "</title>"), resolve)
        self.assertIn("<h1>" + "t" * 100 + "</h1>", s3.info_page(s3.create("ann", "https://news.example/")))
